import{_ as r,l as s,o as a,c as d,v as o,p as l,x as c,d as i,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"yacc / bison","description":"","frontmatter":{"title":"yacc / bison","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/yacc-bison.md","filePath":"cs/yacc-bison.md","lastUpdated":1789023840000}'),h={name:"cs/yacc-bison.md"};function f(u,e,L,b,y,_){const t=s("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="yacc-bison" tabindex="-1">yacc / bison <a class="header-anchor" href="#yacc-bison" aria-label="Permalink to &quot;yacc / bison&quot;">​</a></h1><div class="epigraph"><p>产生式旁边写动作；LALR 生成器交出移进归约表，冲突用优先级声明消解，而不是改写全部左递归。</p><footer>—— 据 Johnson, Yacc: Yet Another Compiler-Compiler；Levine, Flex &amp; Bison；Knuth, 1965；龙书第 4 章整理</footer></div><p>上一课<a href="/cs/lex-flex">lex / flex</a>把字符变成记号。主干已有<a href="/cs/lr-shift-reduce">LR 与移进归约</a>、<a href="/cs/slr-lalr">SLR 与 LALR</a>。缺口不是再构造项集闭包，而是<strong>生成器</strong>：yacc / bison 读 <code>.y</code>，发出 <code>yyparse</code>，并在归约时跑嵌入动作。本课钉接口、冲突报告与 <code>%left</code> 习惯；不手填一张表达式文法的 LALR 表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写递归下降要消左递归；表达式用 LR 可保留左结合产生式。yacc：非终结符、产生式、<code>$$</code>/<code>$1</code> 写语义值。生成期建 LALR(1) 表；运行期栈上是状态与值。缺口是这份<strong>规则到表</strong>的工程，不是再定义 CFG。</p><p>与 lex 的契约：<code>yylex</code> 供记号，<code>YYSTYPE</code> 是语义值联合。错误：<code>yyerror</code>。本课不把错误恢复写完，那是后课。</p><h3 id="left-不是-cfg-的定理" tabindex="-1"><code>%left</code> 不是 CFG 的定理 <a class="header-anchor" href="#left-不是-cfg-的定理" aria-label="Permalink to &quot;`%left` 不是 CFG 的定理&quot;">​</a></h3><p>二义文法（if-else、加减乘）在 LALR 上会移进/归约冲突。bison 用优先级与结合性给冲突格一个确定动作。这是工具约定，语言的无二义性并未被证明——只是表变成函数。</p><p><span class="marginnote"> Johnson 的 yacc 服务 Unix C 编译器。GNU bison 兼容并扩展（<code>%glr-parser</code> 点名，下一课才讲 GLR）。龙书 4.8–4.9 节把生成器当 LALR 的落地。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 <code>.y</code>：记号声明、<code>%%</code>、文法、辅助函数。归约动作里建 AST 节点，不要在动作里做优化。冲突：bison 报告 shift/reduce、reduce/reduce；先看 <code>.output</code> 的状态，再决定改文法还是加优先级。</p>',11)),(a(),l(p,null,{default:c(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%96%87%E6%B3%95%20.y%22%5D%20--%5Cgt%20%20GEN%5B%22yacc%20%2F%20bison%22%5D%0A%20%20GEN%20--%5Cgt%20%20TBL%5B%22LALR%20%E8%A1%A8%20%2B%20yyparse%22%5D%0A%20%20LEX%5B%22yylex%22%5D%20--%5Cgt%20%20TBL%0A%20%20TBL%20--%5Cgt%20%20AST%5B%22%E8%AF%AD%E4%B9%89%E5%80%BC%20%2F%20AST%22%5D%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>中期：把词法规则与语法规则分成两个文件，用共享的记号枚举。不要在 lex 动作里解析表达式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LALR 合并同心项集，表比规范 LR 小，可能引入额外冲突。reduce/reduce 通常是文法真有问题；shift/reduce 在表达式与悬挂 else 上常见。bison 的 <code>%expect</code> 只是把已知冲突数钉死，不是证明正确。</p><p>语义值栈与状态栈同步：归约弹出右部长度，压入 <code>$$</code>。动作里若释放 <code>$1</code> 又把指针放进 <code>$$</code>，所有权要一次说清，否则错误恢复会双释放——后课再收。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Earley，不把 GLR 当默认。不抄 bison 手册的全部指令。后课默认：实用语言的确定文法用 LALR 生成器；认不了的二义与无限前瞻，交给更一般的解析策略。下一课 Earley：任意 CFG，不要表冲突消解。</p><p>优先级声明解决的是生成器的表，不是语言标准里的唯一语法树定义。标准若另有消二义规则，生成器必须与之对齐。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>yacc / bison：CFG + 动作 → LALR 分析器。</li><li>与 lex 经记号种别与 <code>yylval</code> 对接。</li><li>冲突用改文法或优先级；<code>%expect</code> 不是证明。</li><li>出处：Johnson, Yacc；Levine；Knuth, 1965；Aho et al., 龙书。</li></ul>',9))])}const x=r(h,[["render",f]]);export{m as __pageData,x as default};
